// Regex-parses each discovery source's Google News RSS response into
// individual candidate items, tagging each with the discovery source it
// came from. Positional zip against "Filter discovery sources" — safe because
// "Fetch discovery feed" uses onError: continueRegularOutput, which never
// changes item count or order.
//
// Google News RSS is well-formed but idiosyncratic: <link> is a client-side
// JS redirect shell with no server-resolvable target (confirmed empirically
// — see docs/hybrid-discovery-architecture-2026-08-03.md), so the reliable
// signal for "who actually published this" is the <source url> attribute,
// not <link>.

const decodeEntities = (s) => String(s || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;|&apos;/g, "'")
  .replace(/&nbsp;/g, ' ')
  .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const discoverySources = $('Filter discovery sources').all().map(i => i.json);
const fetchResults = $input.all().map(i => i.json);

const candidates = [];
for (let idx = 0; idx < fetchResults.length; idx += 1) {
  const src = discoverySources[idx];
  const res = fetchResults[idx];
  if (!src || !res || res.error) continue;

  const xml = typeof res.data === 'string' ? res.data : (typeof res.body === 'string' ? res.body : '');
  const blocks = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)].map((m) => m[1]);

  for (const block of blocks) {
    const title = (block.match(/<title>([\s\S]*?)<\/title>/) || [])[1] || '';
    const link = (block.match(/<link>([\s\S]*?)<\/link>/) || [])[1] || '';
    const pubDate = (block.match(/<pubDate>([\s\S]*?)<\/pubDate>/) || [])[1] || null;
    const sourceTag = block.match(/<source url="([^"]*)">([^<]*)<\/source>/);
    const description = (block.match(/<description>([\s\S]*?)<\/description>/) || [])[1] || null;

    const cleanTitle = decodeEntities(title);
    if (!cleanTitle || !link.trim()) continue;

    candidates.push({ json: {
      title: cleanTitle,
      link: link.trim(),
      pubDate,
      sourceUrl: sourceTag ? sourceTag[1] : null,
      sourceName: sourceTag ? decodeEntities(sourceTag[2]) : null,
      description: description ? decodeEntities(description) : null,
      discoverySource: src,
    }});
  }
}

console.log(JSON.stringify({ stage: 'discovery_parse', candidates: candidates.length, feeds: discoverySources.length }));
return candidates;

// ── OFFICIAL SOURCE RESOLUTION + GROUPING ───────────────────────────────────
// Mirrors lib/discovery/discovery.ts (resolveDiscoveredItem), the tested
// specification. Every candidate is deduplicated within this run, resolved
// to an official source when the evidence is strong enough, and grouped by
// its final target source so each group becomes ONE dispatch into Workflow
// 02 — identical to how the scheduler dispatches one execution per source.
//
// Nothing here decides what gets PUBLISHED. Every group still goes through
// Normalise RawItem, AI classification and the Publishing Gate exactly like
// an official crawl. This only decides where an item's evidence trail points.
//
// "Get official sources" has no OTHER downstream connection, and n8n's
// execution planner can skip a node that only some other node's expression
// references via $('...') rather than a real graph edge (see
// docs/n8n-fixes-2026-08-02.md, incident #5, for the identical failure mode
// hit and fixed once already in this project). The fix here is the same:
// "Merge for resolution" gives it a REAL edge into this node, and the two
// input streams are told apart by shape — official source rows have
// allowed_domains; parsed candidates have a title and a discoverySource —
// exactly how "Merge state" in Workflows 01/04 already separates settings
// rows from source rows.
const all = $input.all().map((i) => i.json);
// Same in-memory filter as "Filter discovery sources" — only a source the
// database itself would let the scheduler crawl may receive a resolved item.
// Matching a candidate to a pending/blocked/unverified source would only be
// caught later at the Publishing Gate (rule 1 re-reads it anyway), but
// there is no reason to credit an item to a source that cannot publish it.
const officialSources = all.filter(
  (r) => Array.isArray(r.allowed_domains) && r.ingestion_mode !== 'discovery' && r.active === true && r.config_status === 'verified',
);
const parsedCandidates = all.filter((r) => typeof r.title === 'string' && r.discoverySource);

function hostnameOf(url) {
  const m = String(url || '').match(/^https?:\/\/([^/:?#]+)/i);
  return m ? m[1].toLowerCase() : null;
}

function matchOfficialDomain(hostname) {
  if (!hostname) return null;
  const hit = officialSources.find((s) => (s.allowed_domains || []).some((d) => String(d).toLowerCase() === hostname));
  return hit ? { sourceId: hit.id, method: 'domain_match', confidence: 100 } : null;
}

function matchAuthorityMention(title) {
  const text = String(title || '').trim();
  if (!text) return null;
  let best = null;
  for (const s of officialSources) {
    for (const name of [s.authority_ar, s.authority_en]) {
      const candidate = String(name || '').trim();
      if (candidate.length < 4 || !text.includes(candidate)) continue;
      const confidence = Math.min(95, 40 + candidate.length);
      if (!best || confidence > best.confidence) {
        best = { sourceId: s.id, method: 'authority_name_match', confidence, matchedName: candidate };
      }
    }
  }
  return best;
}

const seenTitles = new Set();
const groups = {};

for (const c of parsedCandidates) {
  const normTitle = c.title.replace(/\s+/g, ' ').trim().toLowerCase();
  if (!normTitle || seenTitles.has(normTitle)) continue;
  seenTitles.add(normTitle);

  const domainHit = matchOfficialDomain(hostnameOf(c.sourceUrl));
  let resolved;
  if (domainHit) {
    resolved = { originType: 'official', sourceId: domainHit.sourceId, canonicalUrl: c.sourceUrl, verificationMethod: 'domain_match' };
  } else {
    const nameHit = matchAuthorityMention(c.title);
    if (nameHit && nameHit.confidence >= 60) {
      resolved = { originType: 'official', sourceId: nameHit.sourceId, canonicalUrl: null, verificationMethod: 'authority_name_match' };
    } else {
      resolved = { originType: 'discovery', sourceId: c.discoverySource.id, canonicalUrl: null, verificationMethod: null };
    }
  }

  let publicationDate = null;
  if (c.pubDate) {
    const d = new Date(c.pubDate);
    if (!Number.isNaN(d.getTime())) publicationDate = d.toISOString().slice(0, 10);
  }

  const groupSource = resolved.originType === 'official'
    ? officialSources.find((s) => s.id === resolved.sourceId)
    : c.discoverySource;
  if (!groupSource) continue;

  if (!groups[resolved.sourceId]) groups[resolved.sourceId] = { source: groupSource, items: [] };
  groups[resolved.sourceId].items.push({
    source_url: resolved.canonicalUrl || c.link,
    title_raw: c.title,
    content_raw: c.description || '',
    publication_date: publicationDate,
    attachments: [],
    fetched_at: new Date().toISOString(),
    origin_type: resolved.originType,
    canonical_url: resolved.canonicalUrl,
    discovery_engine: 'google_news',
  });
}

const trigger = $('Called for catch-up').first().json;
const runTag = Date.now();
const dispatches = Object.entries(groups).map(([sourceId, g], i) => ({ json: {
  source: g.source,
  prefetched_items: g.items,
  trigger_type: 'manual',
  dispatched_at: new Date().toISOString(),
  correlation_id: `discovery-${runTag}-${i}`,
  requested_by: trigger.requested_by || null,
  // Same catch-up window Workflow 04 computed — Normalise RawItem in
  // Workflow 02 applies it uniformly to official and discovery items alike.
  window_from: trigger.window_from || null,
  window_to: trigger.window_to || null,
}}));

console.log(JSON.stringify({
  stage: 'discovery_resolve',
  candidates_in: parsedCandidates.length,
  after_dedup: seenTitles.size,
  groups: dispatches.length,
  official_groups: dispatches.filter((d) => d.json.source.ingestion_mode !== 'discovery').length,
}));

if (dispatches.length === 0) {
  return [{ json: { __no_candidates: true } }];
}
return dispatches;

// One health update per DISPATCHED GROUP, not per fetched discovery source —
// last_discovery_success on the group's own row when it IS the discovery
// pseudo-source, last_official_success on the matched row when a group
// resolved to a real official source. A source with zero candidates this
// run (no dispatch group at all) is left untouched rather than stamped with
// a success it did not have — see docs/hybrid-discovery-architecture-
// 2026-08-03.md for what is and is not wired up yet.
const now = new Date().toISOString();
return $input.all().map((entry) => {
  const g = entry.json;
  const isDiscovery = g.source.ingestion_mode === 'discovery';
  return { json: {
    source_id: g.source.id,
    last_discovery_success: isDiscovery ? now : g.source.last_discovery_success,
    last_official_success: isDiscovery ? g.source.last_official_success : now,
    updated_at: now,
  }};
});
